(function(){let websiteId;let traceId;let browser;let language;let visitorCountry;let deviceType;let queue=[];let initialized=false;const API_URL="https://api.funnelquest.com/track";const BATCH_INTERVAL=5e3;const MAX_BATCH_SIZE=10;function init(options){if(initialized){console.warn("FunnelQuest SDK already initialized");return}if(!options||!options.websiteId){throw new Error("websiteId is required")}if(!isValidUUID(options.websiteId)){throw new Error("Invalid websiteId: must be a valid UUID")}websiteId=options.websiteId;traceId=getCookie("fq_trace_id");if(!traceId){traceId=generateTraceId();setCookie("fq_trace_id",traceId,{expires:365,secure:true,sameSite:"Lax"})}else{traceId=sanitizeString(traceId)}browser=getBrowser();language=getLanguage();deviceType=getDeviceType();fetchVisitorCountry().then((country=>{visitorCountry=sanitizeString(country);initialized=true;setInterval(sendBatch,BATCH_INTERVAL)})).catch((err=>{console.error("Failed to fetch visitor country:",err);visitorCountry="unknown";initialized=true;setInterval(sendBatch,BATCH_INTERVAL)}))}function track(event_name){if(!initialized){console.warn("FunnelQuest SDK not initialized. Call init() first.");return}if(!event_name||typeof event_name!=="string"){console.warn("track() requires a valid event_name string");return}const event={websiteId:websiteId,event_name:sanitizeString(event_name),date_time:(new Date).toISOString(),browser:browser,language:language,visitor_country:visitorCountry,device_type:deviceType,trace_id:traceId};queue.push(event);if(queue.length>=MAX_BATCH_SIZE){sendBatch()}}function sendBatch(){if(queue.length===0)return;const batch=queue.slice();queue=[];fetch(API_URL,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(batch)}).then((response=>{if(!response.ok){console.error("Failed to send batch:",response.status)}})).catch((err=>{console.error("Error sending batch:",err)}))}function isValidUUID(str){const regex=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;return regex.test(str)}function generateTraceId(){return"trace-"+Date.now()+"-"+Math.random().toString(36).substr(2,9)}function getCookie(name){const value=`; ${document.cookie}`;const parts=value.split(`; ${name}=`);if(parts.length===2)return parts.pop().split(";").shift();return null}function setCookie(name,value,options){let cookie=`${name}=${encodeURIComponent(value)}`;if(options.expires){const date=new Date;date.setTime(date.getTime()+options.expires*24*60*60*1e3);cookie+=`; expires=${date.toUTCString()}`}cookie+="; path=/";if(options.secure)cookie+="; secure";if(options.sameSite)cookie+=`; samesite=${options.sameSite}`;document.cookie=cookie}function getBrowser(){const ua=navigator.userAgent;if(/chrome|chromium|crios/i.test(ua))return"Chrome";if(/firefox|fxios/i.test(ua))return"Firefox";if(/safari/i.test(ua))return"Safari";if(/edg/i.test(ua))return"Edge";if(/msie|trident/i.test(ua))return"Internet Explorer";return"unknown"}function getLanguage(){return navigator.language||navigator.languages[0]||"en"}function getDeviceType(){const ua=navigator.userAgent;if(/mobile/i.test(ua))return"mobile";if(/tablet/i.test(ua))return"tablet";return"desktop"}function fetchVisitorCountry(){return fetch("https://ipapi.co/json/").then((response=>response.json())).then((data=>data.country_name||"unknown"))}function sanitizeString(str){if(typeof str!=="string")return"";return str.replace(/[\x00-\x1F\x7F]/g,"").trim()}window.funnelQuest={init:init,track:track};window.addEventListener("beforeunload",sendBatch)})();